using System;
using System.IO;
using System.Reflection;
using System.Diagnostics;
using System.Security.Principal;
using System.Security.AccessControl;
using System.Threading;
public static class NativeBackSupport {
 public const string TaskName="RockTekRemote-NativeBack";
 static string Root {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"RockTekRemote","NativeBack");}}
 static bool Admin {get{return new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator);}}
 static void PowerShell(string code){string arg=Convert.ToBase64String(System.Text.Encoding.Unicode.GetBytes("$ErrorActionPreference='Stop';"+code));using(var p=Process.Start(new ProcessStartInfo("powershell.exe","-NoProfile -NonInteractive -EncodedCommand "+arg){UseShellExecute=false,CreateNoWindow=true})){p.WaitForExit();if(p.ExitCode!=0)throw new IOException("Native Back component operation failed: "+p.ExitCode);}}
 static string Q(string s){return "'"+s.Replace("'","''")+"'";}
 static void Elevate(string flag){using(var p=Process.Start(new ProcessStartInfo(Assembly.GetExecutingAssembly().Location,flag){UseShellExecute=true,Verb="runas"})){p.WaitForExit();if(p.ExitCode!=0)throw new IOException("Native Back setup failed: "+p.ExitCode);}}
 public static void Install(){if(!Admin){Elevate("--install-native");return;}InstallMachine();}
 static void CheckRoot(){for(string p=Root;p!=null;p=Path.GetDirectoryName(p))if(Directory.Exists(p)&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new IOException("Native component path is redirected");}
 static void StopMachine(){CheckRoot();string runner=Path.Combine(Root,"service-runner.exe");PowerShell("$t=Get-ScheduledTask -TaskName "+Q(TaskName)+" -ErrorAction SilentlyContinue;if($t){Stop-ScheduledTask -InputObject $t;Unregister-ScheduledTask -InputObject $t -Confirm:$false};if(Test-Path -LiteralPath "+Q(runner)+"){& "+Q(runner)+" --stop;if($LASTEXITCODE){throw 'Native restoration failed'}};$s=Get-CimInstance Win32_Service -Filter \"Name='hidserv'\";if($s.State -eq 'Running'){$loaded=@((Get-Process -Id $s.ProcessId).Modules|Where-Object {$_.FileName -eq "+Q(Path.Combine(Root,"timedhook.dll"))+"});if($loaded.Count){Restart-Service hidserv}};");}
 public static void InstallMachine(){if(!Admin)throw new IOException("Administrator rights required");CheckRoot();StopMachine();Directory.CreateDirectory(Root);var acl=new DirectorySecurity();acl.SetAccessRuleProtection(true,false);var admins=new SecurityIdentifier(WellKnownSidType.BuiltinAdministratorsSid,null);var system=new SecurityIdentifier(WellKnownSidType.LocalSystemSid,null);acl.SetOwner(admins);foreach(var sid in new[]{admins,system})acl.AddAccessRule(new FileSystemAccessRule(sid,FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(WellKnownSidType.AuthenticatedUserSid,null),FileSystemRights.ReadAndExecute,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.SetAccessControl(Path.GetDirectoryName(Root),acl);Directory.SetAccessControl(Root,acl);
 foreach(string name in new[]{"timedhook.dll","service-runner.exe"}){string file=Path.Combine(Root,name);if(File.Exists(file)&&(File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)throw new IOException("Native file is redirected");using(var input=Assembly.GetExecutingAssembly().GetManifestResourceStream(name)){if(input==null)throw new IOException("Native payload missing: "+name);using(var output=new FileStream(file,FileMode.Create,FileAccess.Write,FileShare.None))input.CopyTo(output);}var fa=File.GetAccessControl(file);fa.SetOwner(admins);File.SetAccessControl(file,fa);}
 string app=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","RockTekRemote","RockTekRemote.exe"),exe=Path.Combine(Root,"service-runner.exe");PowerShell("$a=New-ScheduledTaskAction -Execute "+Q(exe)+" -Argument "+Q("--watch \""+app+"\"")+";$tr=New-ScheduledTaskTrigger -AtStartup;$p=New-ScheduledTaskPrincipal -UserId 'S-1-5-18' -LogonType ServiceAccount -RunLevel Highest;$s=New-ScheduledTaskSettingsSet -ExecutionTimeLimit ([TimeSpan]::Zero) -MultipleInstances IgnoreNew -StartWhenAvailable -RestartCount 3 -RestartInterval (New-TimeSpan -Minutes 1) -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries;Register-ScheduledTask -TaskName "+Q(TaskName)+" -Action $a -Trigger $tr -Principal $p -Settings $s -Force|Out-Null;Start-ScheduledTask -TaskName "+Q(TaskName)+";");
 }
 public static void Uninstall(){if(!Directory.Exists(Root))return;if(!Admin){Elevate("--uninstall-native");return;}UninstallMachine();}
 public static void UninstallMachine(){if(!Admin)throw new IOException("Administrator rights required");StopMachine();foreach(string name in new[]{"timedhook.dll","service-runner.exe","runner-phase.log"}){string path=Path.Combine(Root,name);if(File.Exists(path)){if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("Native file redirected");File.Delete(path);}}if(Directory.Exists(Root)&&Directory.GetFileSystemEntries(Root).Length==0)Directory.Delete(Root);}
 public static Mutex Owner(){return new Mutex(false,"Global\\RockTekRemote.BackOwner."+Process.GetCurrentProcess().Id);}
}
